package com.nexushr.controller; import com.nexushr.entity.Holiday; import com.nexushr.dto.RequestDtos.HolidayRequest; import com.nexushr.repository.HolidayRepository; import org.springframework.security.access.prepost.PreAuthorize; import org.springframework.web.bind.annotation.*; import java.time.*; import java.util.*; @RestController @RequestMapping("/holidays") public class HolidayController {final HolidayRepository r;public HolidayController(HolidayRepository r){this.r=r;} @GetMapping public List<Holiday> list(@RequestParam(defaultValue="2000-01-01") LocalDate from,@RequestParam(defaultValue="2100-12-31") LocalDate to){return r.findByDateBetweenOrderByDate(from,to);} @PostMapping @PreAuthorize("hasAnyRole('ADMIN','HR')") public Holiday add(@RequestBody HolidayRequest x){var h=new Holiday();h.setName(x.name());h.setDate(x.date());h.setOptionalHoliday(x.optionalHoliday());return r.save(h);} @DeleteMapping("/{id}") @PreAuthorize("hasRole('ADMIN')") public void delete(@PathVariable UUID id){r.deleteById(id);}}
